		ctx.fillRect(sunX - 520, sunY - 520, 1040, 1040);
		ctx.restore();
		ctx.fillStyle = theme.sun;
		ctx.beginPath();
		ctx.arc(sunX, sunY, 70, 0, Math.PI * 2);
		ctx.fill();
