	const hue = phase * 40 % 360;
	const glow = ctx.createRadialGradient(x, y, size * .2, x, y, radius);
	glow.addColorStop(0, `hsla(${hue}, 100%, 75%, 0.55)`);
	glow.addColorStop(1, `hsla(${hue}, 100%, 70%, 0)`);
