		if (Math.abs(normal.getX(i)) > .5) u = normal.getX(i) > 0 ? .996 : EDGE;
		if (Math.abs(normal.getZ(i)) > .5) v = normal.getZ(i) > 0 ? EDGE : .996;
		uv.setXY(i, u, v);
